    async def list_tasks(
        self,
        service_name: str,
        *,
        function: models.DedicatedHousingTaskFunctionEnum | str | None | NotGiven = NOT_GIVEN,
        status: models.DedicatedTaskStatusEnum | str | None | NotGiven = NOT_GIVEN,
    ) -> list[int]:
        """list_tasks calls GET /v1/dedicated/housing/{serviceName}/task: View task list

        Args:
            service_name: The internal name of your Housing bay
            function: Filter the value of function property (=) (optional)
            status: Filter the value of status property (=) (optional)

        Requires the IAM action dedicatedHousing:apiovh:task/get.
        """
        return await self._call(
            _r.OP_LIST_TASKS,
            path_params={
                "serviceName": service_name,
            },
            query=(
                ("function", function),
                ("status", status),
            ),
            result=list[int],
        )

    async def get_task(self, service_name: str, task_id: int) -> models.DedicatedHousingTask:
        """get_task calls GET /v1/dedicated/housing/{serviceName}/task/{taskId}: Get this object properties

        Args:
            service_name: The internal name of your Housing bay
            task_id: the id of the task

        Requires the IAM action dedicatedHousing:apiovh:task/get.
        """
        return await self._call(
            _r.OP_GET_TASK,
            path_params={
                "serviceName": service_name,
                "taskId": task_id,
            },
            result=models.DedicatedHousingTask,
        )

    def all_tasks(
        self,
        service_name: str,
        *,
        function: models.DedicatedHousingTaskFunctionEnum | str | None | NotGiven = NOT_GIVEN,
        status: models.DedicatedTaskStatusEnum | str | None | NotGiven = NOT_GIVEN,
    ) -> t.AsyncIterator[models.DedicatedHousingTask]:
        """all_tasks iterates over GET /v1/dedicated/housing/{serviceName}/task (View task list).

        It lists the IDs with list_tasks, then gets each object with get_task,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            service_name: The internal name of your Housing bay
            function: Filter the value of function property (=) (optional)
            status: Filter the value of status property (=) (optional)

        The two calls require the IAM action dedicatedHousing:apiovh:task/get.
        """
        return self._each(
            lambda: self.list_tasks(
                service_name,
                function=function,
                status=status,
            ),
            lambda listed_id: self.get_task(service_name, listed_id),
        )

    async def cancel_task(self, service_name: str, task_id: int) -> None:
        """cancel_task calls POST /v1/dedicated/housing/{serviceName}/task/{taskId}/cancel: this action stop the task progression if it's possible

        Args:
            service_name: The internal name of your Housing bay
            task_id: the id of the task

        Requires the IAM action dedicatedHousing:apiovh:task/cancel.
        """
        return await self._call(
            _r.OP_CANCEL_TASK,
            path_params={
                "serviceName": service_name,
                "taskId": task_id,
            },
        )
